WITH payload AS (SELECT $payload$[{"name":"度津神社","slug":"do-tsu-jinja","prefecture":"新潟県","prefecture_slug":"niigata","municipality":"佐渡市","address":"新潟県佐渡市羽茂飯岡550番地4 新潟県佐渡市羽茂飯岡550番地4","latitude":37.860178331,"longitude":138.330811334,"official_url":null,"history":"当社は佐渡国、延喜式内九社の第一にして、古来一ノ宮と称せられる。文明２年（１４７０）６月の羽茂川大洪水に社地流失し、由緒、縁起、古文書はもとより別当坊に至まで悉く烏有に帰したるため、創立年月其の他詳かではないと伝えられています。伝承には諸説あります。","deities":["五十猛命"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=4177","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"射水神社","slug":"imizu-jinja","prefecture":"富山県","prefecture_slug":"toyama","municipality":"高岡市","address":"富山県高岡市古城1-1","latitude":36.748505384,"longitude":137.021558076,"official_url":null,"history":"創始は太古のことで、年代は詳かではないが、延喜式内名神大社であり、越中文化発祥にゆかり深い大守護神として崇敬せられている。伝によれば、養老年間、僧行基二上山麓に養老寺を建て、この神を祀り、二上権現と称したと伝えられています。伝承には諸説あります。","deities":["瓊瓊杵尊"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=4447","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"高瀬神社","slug":"takase-jinja-toyama","prefecture":"富山県","prefecture_slug":"toyama","municipality":"南砺市","address":"富山県南砺市高瀬291","latitude":36.571627886,"longitude":136.947976119,"official_url":null,"history":"御祭神 当神社の御祭神は、大國主命（大己貴命）を主神に天活玉命、五十猛命を祀り、末社３社と礪波地区の村々里々に鎮座されます氏子の神々と越中国延喜式内社三十三座の神々を奉斎したお社でございます。大国主命、縁結び、国土開拓、農耕の神様ですと伝えられています。伝承には諸説あります。","deities":["大己貴命"],"benefits":[],"lineages":["出雲系信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=4457","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"尾山神社","slug":"oyama-jinja-ishikawa","prefecture":"石川県","prefecture_slug":"ishikawa","municipality":"金沢市","address":"石川県金沢市尾山町11-1","latitude":36.566249255,"longitude":136.655842165,"official_url":null,"history":"慶長４年前田利家公の沒後、子弟等は公の霊を神として奉祀しようとしたが、当時憚る所があって、越中国射水郡守山海老坂鳥帽子峰に鎮座の八幡大神を遷座すると称して、その実公の霊を加賀国卯辰山麓に鎮座の卯辰八幡社に奉祀しました。爾来前田家世々崇敬して祭儀怠らなかったが、廃藩置県後旧藩士等祭祀を継続し公の功績を不朽に伝えるため、旧封加越能三州の人士と共に当社を旧藩主金谷邸址に遷そうとして明治５年１０月請願し、翌６年３月許可せられると同時に尾山神社と改称し、同年１１月旧藩主邸址の現社地に御社殿を創建し、１６日に遷座、翌７年２月県社に、同３５年４月２６日に別格官幣社に列せられましたと伝えられています。伝承には諸説あります。","deities":["前田利家"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=4213","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"若狭彦神社","slug":"wakasa-jinja","prefecture":"福井県","prefecture_slug":"fukui","municipality":"小浜市","address":"福井県小浜市竜前28-7","latitude":35.466119998,"longitude":135.778492948,"official_url":"https://wakasahiko-jinja.jp/","history":"若狭彦神社は霊亀元年に竜前へ鎮座したと伝えられています。由緒に関する伝承には諸説あります。","deities":["彦火火出見尊"],"benefits":[],"lineages":[],"sources":[{"name":"若狭彦神社 公式サイト","url":"https://wakasahiko-jinja.jp/about-wakasahikojinja","source_type":"official_site",